}

SELECT ?p ?cls ?name ?tsid WHERE {
  { ?p rdfs:label ?name . } UNION { ?p brick:hasName ?name . }
  ?p a ?cls .
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid . }
}

SELECT ?id ?tsid WHERE {
  ?id ref:hasTimeseriesId ?tsid .
  FILTER (contains(str(?id),"Chiller02") || contains(str(?id),"CondPump01") || contains(str(?id),"CondPump02"))
}

